  recordChange(
    path: string,
    toolName: string,
    stats: DiffStats,
    hunks: DiffHunk[],
    timestamp = Date.now(),
  ): void {
    const entry: SessionChange = {
      path,
      toolName,
      timestamp,
      stats,
      hunks,
    };

    const existing = this.changes.get(path);
    if (existing) {
      existing.push(entry);
    } else {
      this.changes.set(path, [entry]);
    }
  }

